1	import { useDevice } from '@suite/device';
2	import { LearnMoreButton } from '@suite/external-links';
3	import { Translation } from '@suite/intl';
4	import { Anchor, SettingsAnchor, goto } from '@suite/router';
5	import { getCheckBackupUrl } from '@suite-common/suite-utils';
6	import { ActionButton, ActionColumn, SectionItem, TextColumn } from '@trezor/product-components';
7	
8	import { useDispatch } from 'src/hooks/suite';
9	
10	interface CheckRecoverySeedProps {
11	    isDeviceLocked: boolean;
12	}
13	
14	export const CheckRecoverySeed = ({ isDeviceLocked }: CheckRecoverySeedProps) => {
15	    const dispatch = useDispatch();
16	    const { device } = useDevice();
17	
18	    const needsBackup = device?.features?.backup_availability === 'Required';
19	    const learnMoreUrl = getCheckBackupUrl(device);
20	
21	    const handleClick = () =>
22	        dispatch(goto({ routeName: 'recovery-index', params: { cancelable: true } }));
23	
24	    if (needsBackup) return null;
25	
26	    return (
27	        <Anchor anchorId={SettingsAnchor.CheckRecoverySeed}>
28	            {({ anchorId, anchorRef, shouldHighlight }) => (
29	                <SectionItem
30	                    data-testid={anchorId}
31	                    ref={anchorRef}
32	                    shouldHighlight={shouldHighlight}
33	                >
34	                    <TextColumn
35	                        title={<Translation id="TR_CHECK_RECOVERY_SEED" />}
36	                        description={<Translation id="TR_CHECK_RECOVERY_SEED_DESCRIPTION" />}
37	                        bottomContent={
38	                            learnMoreUrl ? <LearnMoreButton url={learnMoreUrl} /> : undefined
39	                        }
40	                    />
41	                    <ActionColumn>
42	                        <ActionButton
43	                            data-testid="@settings/device/check-seed-button"
44	                            onClick={handleClick}
45	                            isDisabled={isDeviceLocked}
46	                            intent="brand"
47	                            isTooltipActive={isDeviceLocked}
48	                            tooltipContent={
49	                                <Translation id="TR_SETTINGS_DEVICE_BANNER_TITLE_REMEMBERED" />
50	                            }
51	                        >
52	                            <Translation id="TR_CHECK_SEED" />
53	                        </ActionButton>
54	                    </ActionColumn>
55	                </SectionItem>
56	            )}
57	        </Anchor>
58	    );
59	};
