1	import { type ReactNode } from 'react';
2	
3	import { TrezorLink } from '@suite/external-links';
4	import { Translation, type TranslationKey } from '@suite/intl';
5	import {
6	    Card,
7	    Flex,
8	    type FlexDirection,
9	    Grid,
10	    Icon,
11	    type IconComponent,
12	    Note,
13	    Paragraph,
14	    Row,
15	    StepList,
16	    type StepListItemState,
17	} from '@trezor/components';
18	import {
19	    CameraSlashIcon,
20	    EyeSlashIcon,
21	    PencilIcon,
22	    RecoverySeedIcon,
23	    TimerIcon,
24	} from '@trezor/icons';
25	import { ESHOP_KEEP_METAL_MULTI_SHARE_URL, HELP_CENTER_SEED_CARD_URL } from '@trezor/urls';
26	
27	import type { Steps } from './steps';
28	
29	type InstructionItemProps = {
30	    direction?: FlexDirection;
31	    icon: IconComponent;
32	    children: ReactNode;
33	};
34	
35	const InstructionItem = ({ direction = 'row', icon, children }: InstructionItemProps) => (
36	    <Card paddingType="normal">
37	        <Flex direction={direction} alignItems="center" gap={8} height="100%">
38	            <Icon size={32} as={icon} />
39	            <Paragraph
40	                typographyStyle="body-sm"
41	                intent="neutral"
42	                priority="secondary"
43	                align={direction === 'column' ? 'center' : 'start'}
44	            >
45	                {children}
46	            </Paragraph>
47	        </Flex>
48	    </Card>
49	);
50	
51	type StepProps = {
52	    time: number;
53	    title: TranslationKey;
54	    children: ReactNode;
55	    state: StepListItemState;
56	};
57	
58	const Step = ({ title, time, children, state }: StepProps) => (
59	    <StepList.Item
60	        title={
61	            <Row gap={12}>
62	                <Translation id={title} />
63	                {state !== 'done' && (
64	                    <Note icon={TimerIcon}>
65	                        <Translation id="TR_N_MIN" values={{ n: time }} />
66	                    </Note>
67	                )}
68	            </Row>
69	        }
70	        state={state}
71	    >
72	        {state === 'default' && children}
73	    </StepList.Item>
74	);
75	
76	type MultiShareBackupStep2to4Props = {
77	    step: Extract<Steps, 'second-info' | 'verify-ownership' | 'backup-seed'>;
78	};
79	
80	export const MultiShareBackupStep2to4 = ({ step }: MultiShareBackupStep2to4Props) => (
81	    <StepList isOrdered margin={{ top: 16 }}>
82	        <Step
83	            time={2}
84	            title="TR_VERIFY_TREZOR_OWNERSHIP"
85	            state={step === 'backup-seed' ? 'done' : 'default'}
