34	        dispatch(backupActions.setInProgress(true));
35	
36	        const result = await TrezorConnect.backupDevice({
37	            ...params,
38	            device: {
39	                path: device.path,
40	            },
41	        });
42	        if (!result.success) {
43	            // When backupDevice fails (e.g. user cancels it) features are not updated in connect so we need to update at suite level
44	            // in order for suite to know it, and do not allow user to recovery again and fail.
45	            await TrezorConnect.getFeatures({ device: { path: device.path } });
46	
47	            dispatch(notificationsActions.addToast({ type: 'backup-failed' }));
48	            dispatch(backupActions.setError(result.error.message));
49	            asTypedDesktopAnalytics(extra.services.analytics).report({
50	                type: events.createBackupEvent.name,
51	                payload: {
52	                    status: 'error',
53	                    error: result.error.message,
54	                },
55	            });
56	        } else {
57	            if (!skipSuccessToast) {
58	                dispatch(notificationsActions.addToast({ type: 'backup-success' }));
59	            }
60	            dispatch(backupActions.setInProgress(false));
61	            asTypedDesktopAnalytics(extra.services.analytics).report({
62	                type: events.createBackupEvent.name,
63	                payload: {
64	                    status: 'finished',
65	                    error: '',
66	                },
67	            });
68	        }
69	    },
70	);
